using namespace port3ds;using namespace bwgame;
struct Point{int x,y;};
static std::vector<Point> flight(const UnitView* units,unsigned count,int width,int height,Point from,Point to){unsigned w=(width+63)/64,h=(height+63)/64;std::vector<int> costs(w*h,1),dist(w*h,1000000000),prev(w*h,-1);for(unsigned i=0;i<count;++i){const auto& u=units[i];if(!u.owner || u.owner>=8 || u.hp<=0)continue;unsigned range=0;switch(u.type){case 0:case 1:case 3:case 8:case 12:case 38:case 43:case 47:case 53:case 66:case 70:case 124:case 144:case 162:range=352;break;default:break;}if(!range)continue;for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w;++x){auto dx=int(x*64+32)-u.x,dy=int(y*64+32)-u.y;auto d=dx*dx+dy*dy;if(d<int(range*range))costs[y*w+x]+=int((range*range-d)/1024)+40;}}auto cell=[&](Point p){return std::min(h-1,unsigned(p.y/64))*w+std::min(w-1,unsigned(p.x/64));};unsigned a=cell(from),b=cell(to);using Node=std::pair<int,unsigned>;std::priority_queue<Node,std::vector<Node>,std::greater<Node>> open;dist[a]=0;open.push({0,a});while(!open.empty()){auto at=open.top();open.pop();auto i=at.second;if(at.first!=dist[i])continue;if(i==b)break;int x=i%w,y=i/w;for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){if(!dx && !dy)continue;int nx=x+dx,ny=y+dy;if(nx<0 || ny<0 || nx>=int(w) || ny>=int(h))continue;unsigned j=ny*w+nx;int d=at.first+costs[j]*(dx && dy?14:10);if(d<dist[j]){dist[j]=d;prev[j]=i;open.push({d,j});}}}assert(prev[b]>=0);std::vector<Point> route;for(int i=b;i!=int(a);i=prev[i])route.push_back({int((i%w)*64+32),int((i/w)*64+32)});std::reverse(route.begin(),route.end());std::vector<Point> turns;for(unsigned k=0;k<route.size();++k){if(k>0 && k+1<route.size()){auto a=route[k-1],b=route[k],c=route[k+1];if((b.x-a.x)*(c.y-b.y)==(b.y-a.y)*(c.x-b.x))continue;}turns.push_back(route[k]);}return turns;}

int main(int argc,char**argv){assert(argc==3);Engine e;assert(e.load(argv[1],argv[2],Scenario::terran_campaign_6));assert(e.start_recording("/tmp/sc3ds-terran06.journal"));e.set_fog_enabled(false);unsigned pending=0,at=0,stage=0,tower_fails=0,landing=0;bool convoy=false;std::vector<Point> route;std::set<unsigned> gas_workers;
for(unsigned frame=0;frame<120000 && e.snapshot().winner<0;++frame){if(!e.tick()){printf("ERROR %s\n",e.error());return 1;}SoundEvent snd[256];e.drain_sounds(snd,256);if(frame%24)continue;UnitView units[1700];unsigned n=e.visible_units(units,1700);std::vector<UnitView> workers,parents,ships;UnitView* raynor=nullptr;const UnitView* refinery=nullptr;for(unsigned i=0;i<n;++i)if(units[i].owner==0){const auto& u=units[i];if(u.completed)parents.push_back(u);if(u.type==7 && u.completed)workers.push_back(u);if(u.type==11)ships.push_back(u);if(u.type==19)raynor=&units[i];if(u.type==110 && u.completed)refinery=&units[i];}
 if(!e.count_units(0,106)){if(frame%120==0)for(const auto& u:parents)if(u.type<106 && e.select(u.x,u.y)){if(u.type==19)e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),320,2544);else e.command(Command::attack,320,2544);}continue;}
 for(const auto& w:workers)if(w.order==unsigned(Orders::PlayerGuard) || w.order==unsigned(Orders::Guard) || w.order==unsigned(Orders::Stop)){const UnitView* target=nullptr;auto id=e.own_unit_at(w.x,w.y);if(refinery && (gas_workers.count(id) || gas_workers.size()<3)){target=refinery;gas_workers.insert(id);}int best=target?0:0x7fffffff;for(unsigned i=0;i<n;++i)if(units[i].mineral){auto dx=units[i].x-w.x,dy=units[i].y-w.y,d=dx*dx+dy*dy;if(d<best){best=d;target=&units[i];}}if(target && e.select(w.x,w.y))e.command(Command::context,target->x,target->y);}
 if(pending && (e.count_units(0,pending) || frame>at+1800))pending=0;auto s=e.snapshot();unsigned want=s.supply_max-s.supply<4?109:!e.count_units(0,110)?110:!e.count_units(0,113)?113:!e.count_units(0,114)?114:0;
 if(!pending && want && !workers.empty() && e.select(workers.back().x,workers.back().y)){bool built=false;if(want==110){for(unsigned i=0;i<n && !built;++i)if(units[i].geyser && e.placement_unit(want,units[i].x,units[i].y).valid)built=e.perform(option_code(OptionKind::build,want),units[i].x,units[i].y);}else for(int ring=2;ring<13 && !built;++ring)for(int y=-ring;y<=ring && !built;++y)for(int x=-ring;x<=ring && !built;++x){if(abs(x)!=ring && abs(y)!=ring)continue;int px=320+x*32,py=2544+y*32;if(e.placement_unit(want,px,py).valid)built=e.perform(option_code(OptionKind::build,want),px,py);}if(built){pending=want;at=frame;}}
 for(const auto& p:parents)if(e.select(p.x,p.y)){if(p.type==106 && e.count_units(0,7)<14 && e.snapshot().queue==0)e.perform(option_code(OptionKind::train,7));if(p.type==114){if(!e.count_units(0,115)){
 if(p.flying){if(p.order!=unsigned(Orders::BuildingLand)){bool landed=false;for(unsigned tries=0;tries<32 && !landed;++tries){unsigned k=landing++;int px=128+int(k%8)*160,py=1904+int((k/8)%6)*160;landed=e.perform(option_code(OptionKind::land),px,py);}}}
 else if(!e.perform(option_code(OptionKind::addon,115))){if(frame%2400==0)printf("Tower at%d,%d: %s\n",p.x,p.y,e.command_status());if(++tower_fails>=8 && e.perform(option_code(OptionKind::liftoff)))tower_fails=0;}
 }else if(e.count_units(0,11)<2 && e.snapshot().queue==0)e.perform(option_code(OptionKind::train,11));}}
 if(!ships.empty() && !convoy){if(raynor && e.select(ships.front().x,ships.front().y))e.perform(option_code(OptionKind::order,unsigned(Orders::PickupTransport)),raynor->x,raynor->y);if(ships.size()>=2){for(const auto& ship:ships)if(ship.cargo){bool gathered=true;for(const auto& q:ships){auto dx=q.x-600,dy=q.y-2400;if(dx*dx+dy*dy>80*80){gathered=false;if(e.select(q.x,q.y))e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),600,2400);}}if(!gathered)break;assert(e.select_similar(ship.x,ship.y,400,2280)>=2);assert(e.store_group(0));route=flight(units,n,s.width*32,s.height*32,{ship.x,ship.y},{2288,2240});convoy=true;printf("Convoy launched%u nodes%zu\n",e.frame(),route.size());break;}}}
 if(convoy && !ships.empty() && e.recall_group(0)){const auto& ship=ships.front();if(stage<route.size()){auto p=route[stage];e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),p.x,p.y);auto dx=ship.x-p.x,dy=ship.y-p.y;if(dx*dx+dy*dy<80*80)++stage;}else{e.perform(option_code(OptionKind::unload));if(raynor && e.select(raynor->x,raynor->y))e.perform(option_code(OptionKind::order,unsigned(Orders::Move)),2288,2240);}}
 if(frame%2400==0){printf("T6 f%u min%d gas%d scv%zu fac%u star%u addon%u ships%zu Raynor%u phase%u\n",e.frame(),s.minerals,s.gas,workers.size(),e.count_units(0,113),e.count_units(0,114),e.count_units(0,115),ships.size(),e.count_units(0,19),stage);fflush(stdout);}
}printf("NoradII result%d f%u Raynor%u dropships%u\n",e.snapshot().winner,e.frame(),e.count_units(0,19),e.count_units(0,11));assert(e.snapshot().winner==0 && e.count_units(0,19)==1);unsigned norad=0;for(unsigned owner=0;owner<8;++owner)norad+=e.count_units(owner,126);assert(norad==1 && convoy);SaveView view;assert(e.save_game("/tmp/sc3ds-terran06-completed.sav",view));Engine replay;SaveView restored;assert(replay.load_save(argv[1],"/tmp/sc3ds-terran06-completed.sav","/tmp/sc3ds-terran06-replay","/tmp/sc3ds-terran06-map",restored));assert(e.state_digest()==replay.state_digest());printf("Norad II original rescue, paid technology/transport, native group flight, surviving Raynor/cruiser and exact completed replay PASS; next=%s\n",e.snapshot().next_scenario.c_str());}
